                      <span className="font-medium">CGST:</span> {formatCurrency(totalCGST)}
                    </p>
                  )}
                  {totalSGST > 0 && (
                    <p className="text-sm text-gray-700">
                      <span className="font-medium">SGST:</span> {formatCurrency(totalSGST)}
                    </p>
                  )}
                  {totalIGST > 0 && (
                    <p className="text-sm text-gray-700">
                      <span className="font-medium">IGST:</span> {formatCurrency(totalIGST)}
                    </p>
                  )}
                  <p className="text-sm font-bold text-gray-900 mt-2 border-t border-gray-300 pt-2">
                    Total: {formatCurrency(grandTotal)}
                  </p>
                </>
              );
            })()}
