  const invoiceDate = new Date(createdAt)
  const now = new Date()
  const threeDaysAgo = new Date(now.getTime() - 3 * 24 * 60 * 60 * 1000)
  return invoiceDate >= threeDaysAgo
}

const extractPan = (gstin) => {
